/**
 * Resolve tech string to matching vector logo
 */
export function getTechLogo(name) {
  if (!name) return techLogos["default"];
  const clean = name.toLowerCase().trim();

  if (clean.includes("typescript")) return techLogos["typescript"];
  if (clean.includes("javascript")) return techLogos["javascript"];
  if (clean.includes("react")) return techLogos["react"];
  if (clean.includes("next")) return techLogos["nextjs"];
  if (clean.includes("node")) return techLogos["nodejs"];
  if (clean.includes("fastify")) return techLogos["fastify"];
  if (clean.includes("express")) return techLogos["express"];
  if (clean.includes("python")) return techLogos["python"];
  if (clean.includes("fastapi")) return techLogos["fastapi"];
  if (clean.includes("postgres")) return techLogos["postgresql"];
  if (clean.includes("redis")) return techLogos["redis"];
  if (clean.includes("docker")) return techLogos["docker"];
  if (clean.includes("linux") || clean.includes("shell") || clean.includes("bash")) return techLogos["linux"];
  if (clean.includes("git")) return techLogos["git"];
  if (clean.includes("pytorch")) return techLogos["pytorch"];
  if (clean.includes("transformer") || clean.includes("hugging")) return techLogos["transformers"];
  if (clean.includes("audio") || clean.includes("sound") || clean.includes("webaudio")) return techLogos["webaudio"];
  if (clean.includes("bullmq") || clean.includes("queue")) return techLogos["bullmq"];
  if (clean.includes("tailwind")) return techLogos["tailwind"];
  if (clean.includes("css")) return techLogos["css"];
  if (clean.includes("html") || clean.includes("a11y")) return techLogos["html"];
  if (clean.includes("jest") || clean.includes("test")) return techLogos["jest"];
  if (clean.includes("numpy")) return techLogos["numpy"];
  if (clean.includes("pandas")) return techLogos["pandas"];
  if (clean.includes("scikit")) return techLogos["scikitlearn"];
  if (clean.includes("jwt") || clean.includes("token")) return techLogos["jwt"];
  if (clean.includes("auth") || clean.includes("security")) return techLogos["security"];
  if (clean.includes("ci/cd") || clean.includes("pipeline") || clean.includes("deploy") || clean.includes("actions")) return techLogos["cicd"];
  if (clean.includes("service worker") || clean.includes("pwa") || clean.includes("worker")) return techLogos["pwa"];
  if (clean.includes("indexeddb") || clean.includes("sqlite") || clean.includes("storage")) return techLogos["sqlite"];
  if (clean.includes("langchain")) return techLogos["langchain"];
  if (clean.includes("ai") || clean.includes("llm") || clean.includes("rag") || clean.includes("model") || clean.includes("openai")) return techLogos["ai"];

  return techLogos["default"];
}
